// Drives the actual Gradle build + signing directly, mirroring
// node_modules/@bubblewrap/cli/dist/lib/cmds/build.js's Build.build() method,
// skipping only the interactive "update project?" checksum prompt (not
// needed — this project was just freshly generated by generate.cjs).
//
// Two bugs in @bubblewrap/core worked around here, both confirmed by direct
// testing in this environment:
//  1. GradleWrapper hardcodes the bare command 'gradlew.bat', which
//     execFile(..., {shell:true}) can't resolve via cwd search on this
//     system. Fixed by calling gradlew.bat via its full (short/no-space)
//     path directly instead of going through GradleWrapper.
//  2. JdkHelper.getEnv() / AndroidSdkTools.getEnv() set env['Path'] (capital
//     P) while the real variable here is env['PATH'] (all caps) — creates a
//     *second*, malformed PATH entry ("...bin\;undefined") rather than
//     extending the real one, and Windows picks whichever wins, breaking
//     bare-name lookups like `jarsigner`. Fixed by building a clean env
//     locally and calling jarsigner.exe via its full path too.
//
// Keystore passwords are read from BUBBLEWRAP_KEYSTORE_PASSWORD /
// BUBBLEWRAP_KEY_PASSWORD env vars (set by run-build.sh from a local file,
// never typed into this script or any command literally).
const path = require("node:path");
const fs = require("node:fs");
const os = require("node:os");
const { execFile } = require("node:child_process");
const { promisify } = require("node:util");
const execFileAsync = promisify(execFile);
const { TwaManifest, JdkHelper, AndroidSdkTools, ConsoleLog } = require("@bubblewrap/core");

// Short-path (8.3) forms throughout — avoids space-in-path breakage with
// execFile's shell:true (confirmed: it concatenates command+args into one
// unescaped string, so "C:\Program Files\..." splits apart at the space).
const TARGET_DIR = "C:\\Users\\ARCHAN~1\\Documents\\trendscope-us\\android";
const JDK_HOME = "C:\\PROGRA~1\\MIE74D~1\\jdk-17.0.21.21-hotspot";
const GRADLEW = path.join(TARGET_DIR, "gradlew.bat");
const JARSIGNER = path.join(JDK_HOME, "bin", "jarsigner.exe");
const APK_BUILD_OUTPUT = path.join(TARGET_DIR, "app\\build\\outputs\\apk\\release\\app-release-unsigned.apk");
const APK_ALIGNED = path.join(TARGET_DIR, "app-release-unsigned-aligned.apk");
const APK_SIGNED = path.join(TARGET_DIR, "app-release-signed.apk");
const BUNDLE_BUILD_OUTPUT = path.join(TARGET_DIR, "app\\build\\outputs\\bundle\\release\\app-release.aab");
const BUNDLE_SIGNED = path.join(TARGET_DIR, "app-release-bundle.aab");

function buildCleanEnv() {
  const env = { ...process.env };
  env.JAVA_HOME = JDK_HOME;
  env.ANDROID_HOME = "C:\\Users\\ARCHAN~1\\.bubblewrap\\android_sdk";
  // Extend the *real* PATH key only — don't create a second differently-cased one.
  const pathKey = Object.keys(env).find((k) => k.toLowerCase() === "path") || "PATH";
  env[pathKey] = path.join(JDK_HOME, "bin") + ";" + (env[pathKey] || "");
  // Known issue in this sandboxed environment: the JVM's NIO Selector pipe
  // (used by Gradle's client<->daemon IPC) tries a Unix-domain socket in
  // the default temp dir and fails with "Unable to establish loopback
  // connection". Fix: point it at a plain writable dir instead.
  // See anthropics/claude-code#44857 / #77508.
  env.JAVA_TOOL_OPTIONS = "-Djdk.net.unixdomain.tmpdir=C:/Temp";
  return env;
}

async function runGradle(task, env) {
  console.log(`Running: gradlew.bat ${task} --stacktrace`);
  const { stdout, stderr } = await execFileAsync(GRADLEW, [task, "--no-daemon", "--stacktrace"], {
    cwd: TARGET_DIR,
    shell: true,
    env,
    maxBuffer: 1024 * 1024 * 50,
  });
  console.log(stdout.slice(-3000));
  if (stderr) console.error(stderr.slice(-2000));
}

async function main() {
  const keystorePassword = process.env.BUBBLEWRAP_KEYSTORE_PASSWORD;
  const keyPassword = process.env.BUBBLEWRAP_KEY_PASSWORD;
  if (!keystorePassword || !keyPassword) {
    throw new Error("BUBBLEWRAP_KEYSTORE_PASSWORD / BUBBLEWRAP_KEY_PASSWORD env vars not set.");
  }

  const env = buildCleanEnv();
  const log = new ConsoleLog("build");
  const config = JSON.parse(fs.readFileSync(path.join(os.homedir(), ".bubblewrap", "config.json"), "utf8"));
  const jdkHelper = new JdkHelper(process, config);
  const androidSdkTools = await AndroidSdkTools.create(process, config, jdkHelper, log);

  if (!(await androidSdkTools.checkBuildTools())) {
    console.log("Installing build tools...");
    await androidSdkTools.installBuildTools();
  }

  const twaManifest = await TwaManifest.fromFile(path.join(TARGET_DIR, "twa-manifest.json"));
  const signingKey = { ...twaManifest.signingKey, path: `"${twaManifest.signingKey.path}"` };

  console.log("Building APK (assembleRelease)...");
  await runGradle("assembleRelease", env);
  await androidSdkTools.zipalignOnlyVerification(APK_BUILD_OUTPUT);
  fs.copyFileSync(APK_BUILD_OUTPUT, APK_ALIGNED);

  console.log("Signing APK...");
  await androidSdkTools.apksigner(
    signingKey.path,
    `"${keystorePassword}"`,
    signingKey.alias,
    `"${keyPassword}"`,
    APK_ALIGNED,
    APK_SIGNED,
  );
  console.log("APK done:", APK_SIGNED);

  console.log("Building App Bundle (bundleRelease)...");
  await runGradle("bundleRelease", env);

  console.log("Signing App Bundle (jarsigner, direct full-path call)...");
  await execFileAsync(
    JARSIGNER,
    [
      "-verbose",
      "-sigalg",
      "SHA256withRSA",
      "-digestalg",
      "SHA-256",
      "-keystore",
      signingKey.path,
      BUNDLE_BUILD_OUTPUT,
      signingKey.alias,
      "-storepass",
      `"${keystorePassword}"`,
      "-keypass",
      `"${keyPassword}"`,
      "-signedjar",
      BUNDLE_SIGNED,
    ],
    { env, shell: true, maxBuffer: 1024 * 1024 * 20 },
  );
  console.log("App Bundle done:", BUNDLE_SIGNED);
}

main().catch((err) => {
  console.error("BUILD FAILED:", err);
  process.exit(1);
});
